    except OverflowError:
        return None
    hours = sorted(fields[1][0])
    minutes = sorted(fields[0][0])
    year, month = first.year, first.month
    while (year, month) <= (limit.year, limit.month):
        if month in fields[3][0]:
            last = calendar.monthrange(year, month)[1]
            start_day = first.day if (year, month) == (first.year, first.month) else 1
            end_day = min(last, limit.day) if (year, month) == (limit.year, limit.month) else last
            for day in range(start_day, end_day + 1):
